नीचे input का `unitPrice` रुपये में ही रखा गया है, लेकिन conversion के बाद सभी गणनाएँ integer पैसे और exact `bigint` intermediates से होती हैं। Output के सभी monetary fields पैसे में हैं।

### चुने गए स्पष्ट नियम

- Minimum की जाँच **membership से पहले**, उस promo के eligible items के subtotal पर होती है। Formula हमेशा बाहर है; `HOME15` के लिए केवल household eligible है।
- Percent discounts हर line पर independently half-up round होते हैं; फिर उन rounded discounts का योग होता है।
- Fixed allocation में proportional shares round करने के बाद बचा धनात्मक/ऋणात्मक remainder सबसे बड़ी **post-membership eligible line** को मिलता है। बराबरी में पहले वाली line चुनी जाती है। यदि बहुत सारी छोटी lines के कारण adjustment उसकी सीमा पार करे, तो अगली सबसे बड़ी line पर जारी रहता है—किसी line की छूट negative या उसकी राशि से अधिक नहीं होती।
- खाली/whitespace code को “कोई promo नहीं” माना है। Rejection priority: `unknown` → `expired` → `no_eligible_items` → `below_minimum`।
- `today` में IST की `YYYY-MM-DD` तारीख या किसी instant का `Date` दिया जा सकता है। Calculation functions pure हैं; केवल entry point का omitted-`today` default वर्तमान clock पढ़ता है। Deterministic उपयोग में `today` दें।
- Invalid cart data programmer/input-validation error है; वह exception देता है। Invalid promo सामान्य checkout result है।

## 1. `pricing.ts`

```ts
// pricing.ts
export type Category = 'grocery' | 'household' | 'infant_formula';

export interface LineItem {
  sku: string;
  name: string;
  unitPrice: number; // रुपये; अधिकतम 2 decimal places
  qty: number;
  category: Category;
}

export interface Cart {
  items: LineItem[];
  memberTier: 'none' | 'plus';
}

export type PromoCode = 'FRESH10' | 'SAVE100' | 'HOME15';
export type PromoRejection =
  | 'unknown'
  | 'expired'
  | 'below_minimum'
  | 'no_eligible_items';

type PromoDefinition = {
  code: PromoCode;
  categories: readonly Category[];
  minimumPaise: number;
  expiresOn: string; // inclusive IST YYYY-MM-DD
} & (
  | { kind: 'percent'; percent: number }
  | { kind: 'fixed'; amountPaise: number }
);

export const PROMOS = [
  {
    code: 'FRESH10',
    kind: 'percent',
    percent: 10,
    categories: ['grocery', 'household'],
    minimumPaise: 100_000,
    expiresOn: '2025-12-31',
  },
  {
    code: 'SAVE100',
    kind: 'fixed',
    amountPaise: 10_000,
    categories: ['grocery', 'household'],
    minimumPaise: 75_000,
    expiresOn: '2025-06-30',
  },
  {
    code: 'HOME15',
    kind: 'percent',
    percent: 15,
    categories: ['household'],
    minimumPaise: 0,
    expiresOn: '2025-12-31',
  },
] as const satisfies readonly PromoDefinition[];

const GST_RATE: Readonly<Record<Category, number>> = {
  grocery: 0,
  household: 18,
  infant_formula: 18,
};

export type PromoResult =
  | { status: 'not_requested' }
  | { status: 'rejected'; code: string; reason: PromoRejection }
  | { status: 'applied'; code: PromoCode };

export interface PricedLine {
  sku: string;
  name: string;
  category: Category;
  qty: number;
  unitPricePaise: number;
  subtotalPaise: number;
  memberDiscountPaise: number;
  promoDiscountPaise: number;
  totalPaise: number; // ग्राहक की GST-inclusive payable राशि
  gstRate: number;
  gstPaise: number; // totalPaise में शामिल
  netExGstPaise: number;
}

export interface CartPrice {
  lines: PricedLine[];
  promo: PromoResult;
  subtotalPaise: number;
  memberDiscountPaise: number;
  promoDiscountPaise: number;
  totalPaise: number;
  gstPaise: number;
  netExGstPaise: number;
}

const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);

function moneyNumber(value: bigint): number {
  if (value < 0n || value > MAX_SAFE) {
    throw new RangeError('Money must fit a non-negative safe integer');
  }
  return Number(value);
}

function assertNatural(value: number, label: string): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${label} must be a non-negative safe integer`);
  }
}

function sumPaise(values: readonly number[]): number {
  return moneyNumber(values.reduce((sum, value) => sum + BigInt(value), 0n));
}

// Non-negative numerator, positive denominator; exact half-up rounding.
function roundRatio(numerator: bigint, denominator: bigint): number {
  return moneyNumber((numerator + denominator / 2n) / denominator);
}

function percentOf(amountPaise: number, percent: number): number {
  return roundRatio(BigInt(amountPaise) * BigInt(percent), 100n);
}

function rupeesToPaise(value: number): number {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError('unitPrice must be finite and non-negative');
  }

  // Decimal parsing avoids binary floating-point multiplication by 100.
  // Over-precision is rejected rather than silently rounded.
  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(String(value));
  if (!match) {
    throw new RangeError('unitPrice must have at most two decimal places');
  }

  const fraction = (match[2] ?? '').padEnd(2, '0');
  return moneyNumber(BigInt(match[1]!) * 100n + BigInt(fraction));
}

/**
 * Proportional fixed discount, capped at total eligible value.
 * Remainder adjustment is largest-first, with stable input-order ties.
 */
export function allocateFixedDiscount(
  requestedPaise: number,
  basesPaise: readonly number[],
): number[] {
  assertNatural(requestedPaise, 'requestedPaise');
  basesPaise.forEach(value => assertNatural(value, 'allocation basis'));

  const basisTotal = sumPaise(basesPaise);
  const target = Math.min(requestedPaise, basisTotal);
  if (target === 0) return basesPaise.map(() => 0);

  const shares = basesPaise.map(basis =>
    roundRatio(BigInt(target) * BigInt(basis), BigInt(basisTotal)),
  );

  // Use bigint even for the temporary rounded sum: it may overshoot target.
  let remainder =
    BigInt(target) -
    shares.reduce((sum, share) => sum + BigInt(share), 0n);

  const largestFirst = basesPaise
    .map((basis, index) => ({ basis, index }))
    .sort((a, b) => b.basis - a.basis || a.index - b.index);

  for (const { basis, index } of largestFirst) {
    if (remainder === 0n) break;

    const current = shares[index]!;
    const capacity = BigInt(remainder > 0n ? basis - current : current);
    const needed = remainder > 0n ? remainder : -remainder;
    const adjustment = capacity < needed ? capacity : needed;
    const signed = remainder > 0n ? adjustment : -adjustment;

    shares[index] = moneyNumber(BigInt(current) + signed);
    remainder -= signed;
  }

  if (remainder !== 0n) throw new Error('Allocation invariant violated');
  return shares;
}

function toIstDate(today: Date | string): string {
  if (typeof today === 'string') {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      throw new RangeError('today must be an IST YYYY-MM-DD date');
    }
    const parsed = new Date(`${today}T00:00:00.000Z`);
    if (
      !Number.isFinite(parsed.getTime()) ||
      parsed.toISOString().slice(0, 10) !== today
    ) {
      throw new RangeError('Invalid calendar date');
    }
    return today;
  }

  if (!Number.isFinite(today.getTime())) {
    throw new RangeError('Invalid Date');
  }

  // IST is UTC+05:30, with no daylight-saving adjustment.
  const shifted = new Date(today.getTime() + 330 * 60_000);
  return toIstDate(shifted.toISOString().slice(0, 10));
}

interface PreparedLine {
  item: LineItem;
  unitPricePaise: number;
  subtotalPaise: number;
  memberDiscountPaise: number;
  remainingPaise: number;
}

function prepareLines(cart: Cart): PreparedLine[] {
  if (cart.memberTier !== 'none' && cart.memberTier !== 'plus') {
    throw new RangeError('Invalid memberTier');
  }

  return cart.items.map(item => {
    if (!Object.prototype.hasOwnProperty.call(GST_RATE, item.category)) {
      throw new RangeError('Invalid category');
    }
    if (!Number.isSafeInteger(item.qty) || item.qty <= 0) {
      throw new RangeError('qty must be a positive safe integer');
    }

    const unitPricePaise = rupeesToPaise(item.unitPrice);
    const subtotalPaise = moneyNumber(
      BigInt(unitPricePaise) * BigInt(item.qty),
    );
    const memberDiscountPaise =
      cart.memberTier === 'plus' && item.category !== 'infant_formula'
        ? percentOf(subtotalPaise, 5)
        : 0;

    return {
      item,
      unitPricePaise,
      subtotalPaise,
      memberDiscountPaise,
      remainingPaise: subtotalPaise - memberDiscountPaise,
    };
  });
}

function calculatePromo(
  lines: readonly PreparedLine[],
  promoCode: string | undefined,
  todayIst: string,
): { promo: PromoResult; discounts: number[] } {
  const zeros = lines.map(() => 0);
  const code = promoCode?.trim().toUpperCase();

  if (!code) {
    return { promo: { status: 'not_requested' }, discounts: zeros };
  }

  const reject = (reason: PromoRejection) => ({
    promo: { status: 'rejected' as const, code, reason },
    discounts: zeros,
  });

  const definition: PromoDefinition | undefined =
    PROMOS.find(promo => promo.code === code);

  if (!definition) return reject('unknown');
  if (todayIst > definition.expiresOn) return reject('expired');

  // Legal exclusion is enforced independently of the configuration table.
  const eligible = lines.map(line =>
    line.item.category !== 'infant_formula' &&
    definition.categories.includes(line.item.category),
  );

  const bases = lines.map((line, index) =>
    eligible[index] ? line.remainingPaise : 0,
  );

  if (sumPaise(bases) === 0) return reject('no_eligible_items');

  const eligibleSubtotal = sumPaise(
    lines.map((line, index) =>
      eligible[index] ? line.subtotalPaise : 0,
    ),
  );

  if (eligibleSubtotal < definition.minimumPaise) {
    return reject('below_minimum');
  }

  const discounts =
    definition.kind === 'fixed'
      ? allocateFixedDiscount(definition.amountPaise, bases)
      : bases.map(basis => percentOf(basis, definition.percent));

  return {
    promo: { status: 'applied', code: definition.code },
    discounts,
  };
}

// Pure pricing core: date is already explicit and normalized.
function calculateCart(
  cart: Cart,
  promoCode: string | undefined,
  todayIst: string,
): CartPrice {
  const prepared = prepareLines(cart);
  const subtotalPaise = sumPaise(
    prepared.map(line => line.subtotalPaise),
  );
  const { promo, discounts } = calculatePromo(
    prepared,
    promoCode,
    todayIst,
  );

  const lines: PricedLine[] = prepared.map((line, index) => {
    const promoDiscountPaise = discounts[index]!;
    const totalPaise = line.remainingPaise - promoDiscountPaise;
    const gstRate = GST_RATE[line.item.category];
    const gstPaise = roundRatio(
      BigInt(totalPaise) * BigInt(gstRate),
      BigInt(100 + gstRate),
    );

    return {
      sku: line.item.sku,
      name: line.item.name,
      category: line.item.category,
      qty: line.item.qty,
      unitPricePaise: line.unitPricePaise,
      subtotalPaise: line.subtotalPaise,
      memberDiscountPaise: line.memberDiscountPaise,
      promoDiscountPaise,
      totalPaise,
      gstRate,
      gstPaise,
      netExGstPaise: totalPaise - gstPaise,
    };
  });

  return {
    lines,
    promo,
    subtotalPaise,
    memberDiscountPaise: sumPaise(
      lines.map(line => line.memberDiscountPaise),
    ),
    promoDiscountPaise: sumPaise(
      lines.map(line => line.promoDiscountPaise),
    ),
    totalPaise: sumPaise(lines.map(line => line.totalPaise)),
    gstPaise: sumPaise(lines.map(line => line.gstPaise)),
    netExGstPaise: sumPaise(lines.map(line => line.netExGstPaise)),
  };
}

export function priceCart(
  cart: Cart,
  promoCode?: string,
  today?: Date | string,
): CartPrice {
  return calculateCart(
    cart,
    promoCode,
    toIstDate(today ?? new Date()),
  );
}
```

