import { describe, expect, it } from 'vitest';
import {
  allocateFixedDiscount,
  priceCart,
  type Cart,
  type Category,
  type LineItem,
} from './pricing';

const VALID_DAY = '2025-06-01';

function item(
  unitPrice: number,
  category: Category = 'grocery',
  qty = 1,
  sku = 'sku',
): LineItem {
  return { sku, name: sku, unitPrice, qty, category };
}

function cart(
  items: LineItem[],
  memberTier: Cart['memberTier'] = 'none',
): Cart {
  return { items, memberTier };
}

describe('promo eligibility and membership', () => {
  it('normalizes code; checks minimum before membership; applies member first', () => {
    const result = priceCart(
      cart([item(1000)], 'plus'),
      ' fresh10 ',
      VALID_DAY,
    );

    expect(result.promo).toEqual({
      status: 'applied',
      code: 'FRESH10',
    });
    expect(result.subtotalPaise).toBe(100_000);
    expect(result.memberDiscountPaise).toBe(5_000);
    expect(result.promoDiscountPaise).toBe(9_500);
    expect(result.totalPaise).toBe(85_500);
    expect(result.gstPaise).toBe(0);
  });

  it.each([
    ['FRESH10', 999.99, 1000],
    ['SAVE100', 749.99, 750],
  ])('%s minimum is inclusive', (code, below, minimum) => {
    expect(
      priceCart(cart([item(below)]), code, VALID_DAY).promo,
    ).toMatchObject({ status: 'rejected', reason: 'below_minimum' });

    expect(
      priceCart(cart([item(minimum)]), code, VALID_DAY).promo,
    ).toMatchObject({ status: 'applied' });
  });

  it('does not count formula toward the minimum', () => {
    for (const [code, amount] of [
      ['FRESH10', 999.99],
      ['SAVE100', 749.99],
    ] as const) {
      const result = priceCart(
        cart([item(amount), item(2000, 'infant_formula')]),
        code,
        VALID_DAY,
      );
      expect(result.promo).toMatchObject({
        status: 'rejected',
        reason: 'below_minimum',
      });
    }
  });

  it.each(['FRESH10', 'SAVE100', 'HOME15'])(
    '%s never discounts formula, including membership',
    code => {
      const result = priceCart(
        cart([
          item(1000),
          item(1000, 'household'),
          item(449, 'infant_formula'),
        ], 'plus'),
        code,
        VALID_DAY,
      );

      expect(result.promo.status).toBe('applied');
      expect(result.lines[2]).toMatchObject({
        memberDiscountPaise: 0,
        promoDiscountPaise: 0,
        totalPaise: 44_900,
        gstPaise: 6_849,
      });
    },
  );

  it('HOME15 targets only household, after membership', () => {
    const result = priceCart(
      cart([
        item(100, 'grocery'),
        item(100, 'household'),
        item(100, 'infant_formula'),
      ], 'plus'),
      'HOME15',
      VALID_DAY,
    );

    expect(result.lines.map(line => line.memberDiscountPaise))
      .toEqual([500, 500, 0]);
    expect(result.lines.map(line => line.promoDiscountPaise))
      .toEqual([0, 1425, 0]);
    expect(result.lines.map(line => line.totalPaise))
      .toEqual([9500, 8075, 10_000]);
  });

  it.each([
    [cart([]), 'FRESH10'],
    [cart([item(500, 'infant_formula')]), 'SAVE100'],
    [cart([item(1000)]), 'HOME15'],
    [cart([item(0, 'household')]), 'HOME15'],
  ])('reports no positive eligible amount', (input, code) => {
    expect(priceCart(input, code, VALID_DAY).promo).toMatchObject({
      status: 'rejected',
      reason: 'no_eligible_items',
    });
  });

  it('invalid codes preserve the no-promo checkout, including membership', () => {
    const input = cart([item(1000, 'household')], 'plus');
    const baseline = priceCart(input, undefined, VALID_DAY);

    for (const code of [
      'BOGUS',
      '__proto__',
      'FRESH10,SAVE100',
    ]) {
      const result = priceCart(input, code, VALID_DAY);
      expect(result.promo).toEqual({
        status: 'rejected',
        code: code.toUpperCase(),
        reason: 'unknown',
      });
      expect({ ...result, promo: baseline.promo }).toEqual(baseline);
    }

    expect(priceCart(input, '   ', VALID_DAY)).toEqual(baseline);
  });
});

describe('IST expiry', () => {
  it.each([
    ['FRESH10', '2025-12-31', '2026-01-01'],
    ['SAVE100', '2025-06-30', '2025-07-01'],
    ['HOME15', '2025-12-31', '2026-01-01'],
  ])('%s includes its final local date', (code, lastDay, nextDay) => {
    const input = cart([item(1000, 'household')]);
