    const expired = priceCart(input, code, nextDay);
    expect(expired.promo).toMatchObject({
      status: 'rejected',
      reason: 'expired',
    });
    const baseline = priceCart(input, undefined, nextDay);
    expect({ ...expired, promo: baseline.promo }).toEqual(baseline);
  });

  it('switches at IST midnight, not UTC midnight', () => {
    const input = cart([item(1000)]);

    expect(priceCart(
      input,
      'FRESH10',
      new Date('2025-12-31T18:29:59.999Z'),
    ).promo.status).toBe('applied');

    expect(priceCart(
      input,
      'FRESH10',
      new Date('2025-12-31T18:30:00.000Z'),
    ).promo).toMatchObject({ reason: 'expired' });
  });

  it('validates explicit calendar dates', () => {
    expect(() => priceCart(cart([]), undefined, '2025-02-30'))
      .toThrow(RangeError);
    expect(() => priceCart(cart([]), undefined, new Date(NaN)))
      .toThrow(RangeError);
  });
});

describe('rounding, allocation and inclusive GST', () => {
  it('rounds membership half-up per line, not once on the cart', () => {
    const result = priceCart(
      cart([item(0.10), item(0.10)], 'plus'),
      undefined,
      VALID_DAY,
    );
    expect(result.lines.map(line => line.memberDiscountPaise))
      .toEqual([1, 1]);
    expect(result.memberDiscountPaise).toBe(2);
    expect(result.totalPaise).toBe(18);
  });

  it('rounds percent promo half-up per line', () => {
    const result = priceCart(
      cart([item(0.10, 'household'), item(0.10, 'household')]),
      'HOME15',
      VALID_DAY,
    );
    expect(result.lines.map(line => line.promoDiscountPaise))
      .toEqual([2, 2]); // 1.5 paise each
    expect(result.totalPaise).toBe(16);
  });

  it('uses rounded membership remainder as the promo basis', () => {
    const result = priceCart(
      cart([item(0.10, 'household')], 'plus'),
      'HOME15',
      VALID_DAY,
    );
    expect(result.lines[0]).toMatchObject({
      subtotalPaise: 10,
      memberDiscountPaise: 1,
      promoDiscountPaise: 1, // 15% of 9 paise
      totalPaise: 8,
      gstPaise: 1,
    });
  });

  it('allocates SAVE100 after membership and extracts GST afterward', () => {
    const result = priceCart(
      cart([item(250), item(500, 'household')], 'plus'),
      'SAVE100',
      VALID_DAY,
    );

    expect(result.lines.map(line => line.memberDiscountPaise))
      .toEqual([1250, 2500]);
    expect(result.lines.map(line => line.promoDiscountPaise))
      .toEqual([3333, 6667]);
    expect(result.lines.map(line => line.totalPaise))
      .toEqual([20_417, 40_833]);
    expect(result.lines.map(line => line.gstPaise))
      .toEqual([0, 6229]);
    expect(result.totalPaise).toBe(61_250);
  });

  it('assigns fixed rounding remainder to the largest eligible line', () => {
    const result = priceCart(
      cart([item(250), item(250), item(250.01)]),
      'SAVE100',
      VALID_DAY,
    );
    expect(result.lines.map(line => line.promoDiscountPaise))
      .toEqual([3333, 3333, 3334]);
    expect(result.promoDiscountPaise).toBe(10_000);
  });

  it('handles positive/negative remainders and stable ties', () => {
    expect(allocateFixedDiscount(10_000, [25_000, 25_000, 25_000]))
      .toEqual([3334, 3333, 3333]);

    // Rounded shares: [1, 2], so subtract the extra paise from largest.
    expect(allocateFixedDiscount(2, [1, 3])).toEqual([1, 1]);

    // Equal largest lines: signed remainder goes to the first.
    expect(allocateFixedDiscount(1, [1, 1])).toEqual([0, 1]);
  });

  it('caps fixed discounts and handles zero bases', () => {
    expect(allocateFixedDiscount(10_000, [0, 1, 2]))
      .toEqual([0, 1, 2]);
    expect(allocateFixedDiscount(10_000, [0, 0])).toEqual([0, 0]);
    expect(allocateFixedDiscount(10_000, [])).toEqual([]);
  });

  it('spills correction to the next line rather than going negative', () => {
    expect(allocateFixedDiscount(2, [1, 1, 1, 1]))
      .toEqual([0, 0, 1, 1]);
  });

  it('preserves allocation sum and bounds across small edge cases', () => {
    for (let a = 0; a <= 6; a++) {
      for (let b = 0; b <= 6; b++) {
        for (let requested = 0; requested <= 20; requested++) {
          const bases = [a, b, 1];
          const shares = allocateFixedDiscount(requested, bases);

          expect(shares.reduce((s, v) => s + v, 0))
            .toBe(Math.min(requested, a + b + 1));

          shares.forEach((share, index) => {
            expect(Number.isInteger(share)).toBe(true);
            expect(share).toBeGreaterThanOrEqual(0);
            expect(share).toBeLessThanOrEqual(bases[index]!);
          });
        }
      }
    }
  });

