    const result = priceCart(
      cart([
        item(118),
        item(118, 'household'),
        item(118, 'infant_formula'),
      ]),
      undefined,
      VALID_DAY,
    );

    expect(result.totalPaise).toBe(35_400);
    expect(result.lines.map(line => line.gstPaise))
      .toEqual([0, 1800, 1800]);
    expect(result.netExGstPaise + result.gstPaise)
      .toBe(result.totalPaise);
  });

  it('rounds GST on each line, not on aggregate payable', () => {
    const result = priceCart(
      cart([item(0.03, 'household'), item(0.03, 'household')]),
      undefined,
      VALID_DAY,
    );
    expect(result.gstPaise).toBe(0); // each: 3 × 18 / 118 → 0

    expect(priceCart(
      cart([item(0.10, 'household')]),
      undefined,
      VALID_DAY,
    ).gstPaise).toBe(2);
  });

  it('converts decimal rupees exactly and multiplies quantity first', () => {
    const result = priceCart(
      cart([item(1.15, 'grocery', 3)]),
      undefined,
      VALID_DAY,
    );
    expect(result.lines[0]?.unitPricePaise).toBe(115);
    expect(result.subtotalPaise).toBe(345);
  });
});

describe('validation, purity and requested example', () => {
  it('rejects invalid prices, quantities and unsafe monetary totals', () => {
    for (const price of [-1, NaN, Infinity, 0.001]) {
      expect(() => priceCart(
        cart([item(price)]), undefined, VALID_DAY,
      )).toThrow(RangeError);
    }

    for (const qty of [0, -1, 1.5]) {
      expect(() => priceCart(
        cart([item(1, 'grocery', qty)]), undefined, VALID_DAY,
      )).toThrow(RangeError);
    }

    expect(() => priceCart(
      cart([item(1, 'grocery', Number.MAX_SAFE_INTEGER)]),
      undefined,
      VALID_DAY,
    )).toThrow(RangeError);

    expect(() => priceCart(
      cart([item(50_000_000_000_000), item(50_000_000_000_000)]),
      undefined,
      VALID_DAY,
    )).toThrow(RangeError);
  });

  it('does not mutate its inputs and is deterministic with an explicit date', () => {
    const input = cart([item(1000, 'household')], 'plus');
    const before = structuredClone(input);
    const date = new Date('2025-06-01T00:00:00Z');
    const timestamp = date.getTime();

    const first = priceCart(input, 'HOME15', date);
    expect(priceCart(input, 'HOME15', date)).toEqual(first);
    expect(input).toEqual(before);
    expect(date.getTime()).toBe(timestamp);
  });

  it('prices the supplied example', () => {
    const input = cart([
      item(189, 'grocery', 2, 'apple'),
      item(46.50, 'grocery', 1, 'banana'),
      item(214, 'grocery', 1, 'eggs'),
      item(112.50, 'household', 2, 'dishwash'),
      item(449, 'infant_formula', 1, 'formula'),
    ], 'plus');

    const result = priceCart(input, 'fresh10', '2025-07-02');

    expect(result.promo).toEqual({
      status: 'rejected',
      code: 'FRESH10',
      reason: 'below_minimum',
    });
    expect(result).toMatchObject({
      subtotalPaise: 131_250,
      memberDiscountPaise: 4318,
      promoDiscountPaise: 0,
      totalPaise: 126_932,
      gstPaise: 10_110,
      netExGstPaise: 116_822,
    });
    expect(result.lines.map(line => line.totalPaise))
      .toEqual([35_910, 4417, 20_330, 21_375, 44_900]);

    const baseline = priceCart(input, undefined, '2025-07-02');
    expect({ ...result, promo: baseline.promo }).toEqual(baseline);
  });
});
